const ALLOWED = {
    ph: { unit: 'pH', min: 0, max: 14 },
    turbidity: { unit: 'NTU', min: 0, max: Infinity },
    conductivity: { unit: 'uS/cm', min: 0, max: Infinity },
    chlorine_residual: { unit: 'mg/L', min: 0, max: Infinity },
    temperature: { unit: '°C', min: -5, max: 100 }
};

function reject(reason, detail) {
    const raw = msg.payload;
    let preview;
    try { preview = typeof raw === 'string' ? raw : JSON.stringify(raw); }
    catch (e) { preview = String(raw); }
    return [null, {
        topic: msg.topic,
        payload: {
            accepted: false,
            reason,
            detail: String(detail || '').slice(0, 200),
            source_topic: msg.topic,
            packet: String(preview || '').slice(0, 500),
            rejected_at: new Date().toISOString()
        }
    }];
}

let p = msg.payload;
if (Buffer.isBuffer(p)) p = p.toString('utf8');
if (typeof p === 'string') {
    try { p = JSON.parse(p); }
    catch (e) { return reject('bad_json', e.message); }
}
if (!p || typeof p !== 'object' || Array.isArray(p)) {
    return reject('bad_shape', 'Expected a JSON object');
}

const parts = String(msg.topic || '').split('/');
if (parts.length < 4 || parts[0] !== 'hre' || parts[1] !== 'water-quality-telemetry' || parts[2] !== 'harare') {
    return reject('bad_topic', msg.topic);
}
if (typeof p.sensor_id !== 'string' || !p.sensor_id.trim()) {
    return reject('missing_sensor_id', 'sensor_id must be a non-empty string');
}
const topicSensor = parts.length === 4 ? parts[3] : null;
if (topicSensor && topicSensor !== p.sensor_id) {
    return reject('topic_sensor_mismatch', 'Topic sensor does not match payload sensor_id');
}

let ts = p.ts !== undefined ? p.ts : p.timestamp;
let millis = ts === undefined ? Date.now() : (typeof ts === 'number' ? (ts < 1e12 ? ts * 1000 : ts) : Date.parse(ts));
if (!Number.isFinite(millis)) return reject('bad_timestamp', ts);
if (millis > Date.now() + 5 * 60 * 1000) return reject('timestamp_in_future', ts);
if (millis < Date.now() - 30 * 86400000) return reject('timestamp_too_old', ts);
const normalizedTime = new Date(millis).toISOString();

let candidates;
if (p.readings && typeof p.readings === 'object' && !Array.isArray(p.readings)) {
    candidates = Object.entries(p.readings);
} else if (typeof p.metric_type === 'string' && p.value !== undefined) {
    candidates = [[p.metric_type, p.value]];
} else {
    return reject('missing_reading', 'Provide metric_type and value, or a readings object');
}

const quality = p.quality_status === undefined ? 'valid' : p.quality_status;
if (!['valid', 'suspect', 'invalid'].includes(quality)) {
    return reject('bad_quality_status', quality);
}

const accepted = [];
const dropped = [];
for (const [metric, raw] of candidates) {
    const spec = ALLOWED[metric];
    if (!spec) { dropped.push({ metric, reason: 'unknown_metric' }); continue; }
    const value = (typeof raw === 'string' && raw.trim() !== '') ? Number(raw) : raw;
    if (typeof value !== 'number' || !Number.isFinite(value)) {
        dropped.push({ metric, reason: 'not_numeric' }); continue;
    }
    if (value < spec.min || value > spec.max) {
        dropped.push({ metric, reason: 'implausible_value' }); continue;
    }
    accepted.push({
        topic: msg.topic,
        payload: {
            sensor_id: p.sensor_id,
            municipality: 'harare',
            metric_type: metric,
            value,
            unit: spec.unit,
            ts: normalizedTime,
            quality_status: quality,
            source_topic: msg.topic,
            edge_received_at: new Date().toISOString()
        }
    });
}
if (accepted.length === 0) return reject(dropped.length ? 'no_valid_readings' : 'no_readings', dropped);
if (dropped.length) node.warn('Some readings were rejected for sensor ' + p.sensor_id + ': ' + JSON.stringify(dropped));
node.status({ fill: 'green', shape: 'dot', text: p.sensor_id + ' | accepted ' + accepted.length });
return [accepted, null];

const pool = global.get('hre_pool:harare');
if (!pool) {
    node.error('Water-quality PostgreSQL pool is not initialized. Check the Function node On Start and PostgreSQL environment settings.', msg);
    return null;
}

const r = msg.payload;
const allowedMetrics = ['ph', 'turbidity', 'conductivity', 'chlorine_residual', 'temperature'];

if (!r || typeof r !== 'object' ||
    typeof r.sensor_id !== 'string' || !r.sensor_id ||
    !allowedMetrics.includes(r.metric_type) ||
    typeof r.value !== 'number' || !Number.isFinite(r.value) ||
    !r.ts) {
    node.error('Invalid normalized water-quality reading; insert skipped.', msg);
    return null;
}

const sql = `
    INSERT INTO water_quality_telemetry
        (time, sensor_id, metric_type, value, edge_received_at, received_at, quality_status)
    VALUES
        ($1::timestamptz, $2, $3, $4, $5::timestamptz, now(), $6)
    ON CONFLICT (sensor_id, metric_type, time) DO NOTHING
    RETURNING time, sensor_id, metric_type, value, quality_status
`;

const params = [
    r.ts,
    r.sensor_id,
    r.metric_type,
    r.value,
    r.edge_received_at || r.ts,
    r.quality_status || 'valid'
];

pool.query(sql, params)
    .then(result => {
        if (result.rowCount === 0) {
            node.status({ fill: 'yellow', shape: 'ring', text: 'duplicate skipped' });
            node.warn('Duplicate water-quality reading skipped: ' + r.sensor_id + ' / ' + r.metric_type + ' / ' + r.ts);
            return;
        }
        msg.topic = 'water_quality_inserted';
        msg.payload = result.rows[0];
        node.status({ fill: 'green', shape: 'dot', text: 'inserted ' + r.sensor_id });
        node.send(msg);
    })
    .catch(err => {
        node.status({ fill: 'red', shape: 'ring', text: 'database insert failed' });
        node.error('Water-quality database insert failed: ' + err.message, msg);
    });

return null;

