const p = global.get('hre_pool:harare');
const r = msg.payload;

if (!p) {
    node.error("Harare PostgreSQL pool is unavailable", msg);
    return;
}

if (!r || !r.sensor_id || !r.metric_type ||
    r.value === undefined || r.value === null) {
    node.error("Missing sensor_id, metric_type, or value", msg);
    return;
}

const sql = `
    SELECT
        l.limit_id,
        l.warning_min,
        l.warning_max,
        l.critical_min,
        l.critical_max,
        l.unit,
        l.description
    FROM public.water_quality_sensor s
    JOIN public.water_quality_limits l
      ON l.metric_type = $2
     AND l.enabled = TRUE
     AND (l.ward_id IS NULL OR l.ward_id = s.ward_id)
     AND l.asset_id IS NULL
    WHERE s.sensor_id = $1
      AND s.active = TRUE
    ORDER BY
      (l.ward_id IS NOT NULL) DESC,
      l.created_at DESC
`;

p.query(sql, [r.sensor_id, r.metric_type])
.then(result => {
    if (result.rows.length === 0) {
        msg.threshold = {
            status: "no_limit_configured",
            severity: "unknown",
            message: "No applicable threshold found"
        };
        node.send(msg);
        return;
    }

    const limit = result.rows[0];
    const value = Number(r.value);

    let severity = "normal";

    if (
        (limit.critical_min !== null &&
         value < Number(limit.critical_min)) ||
        (limit.critical_max !== null &&
         value > Number(limit.critical_max))
    ) {
        severity = "critical";
    } else if (
        (limit.warning_min !== null &&
         value < Number(limit.warning_min)) ||
        (limit.warning_max !== null &&
         value > Number(limit.warning_max))
    ) {
        severity = "warning";
    }

    msg.threshold = {
        status: "evaluated",
        severity,
        limit_id: limit.limit_id,
        metric_type: r.metric_type,
        sensor_id: r.sensor_id,
        value,
        unit: limit.unit,
        description: limit.description
    };

    node.send(msg);
})
.catch(err => {
    node.error("WQ threshold query failed: " + err.message, msg);
});

return;

const p = global.get('hre_pool:harare');
const r = msg.payload;
const t = msg.threshold;

if (!p) {
    node.error("Harare PostgreSQL pool is unavailable", msg);
    return;
}

if (!t || t.status !== "evaluated") {
    node.warn("Skipping event creation: threshold was not evaluated");
    return;
}

// Normal readings do not create events.
if (t.severity === "normal") {
    msg.decision = {
        status: "no_event",
        reason: "Reading is within configured limits"
    };
    node.send(msg);
    return;
}

if (!["warning", "critical"].includes(t.severity)) {
    node.error("Unexpected threshold severity", msg);
    return;
}

const metric = r.metric_type;
const sensor = r.sensor_id;
const value = Number(r.value);
const severity = t.severity;

let recommendation;

if (metric === "turbidity" && severity === "critical") {
    recommendation =
        "Verify the reading and inspect the turbidity sensor. " +
        "Check filter condition, treatment process records, and " +
        "upstream conditions. Confirm findings with the operator " +
        "before considering any isolation or treatment change.";
} else if (metric === "turbidity") {
    recommendation =
        "Verify the turbidity reading, inspect sensor condition, " +
        "and review filter performance and recent readings.";
} else if (metric === "ph" && severity === "critical") {
    recommendation =
        "Verify the pH reading using an appropriate independent " +
        "measurement. Check sensor calibration and review treatment " +
        "process conditions. Notify the responsible operator for assessment.";
} else if (metric === "ph") {
    recommendation =
        "Verify the pH reading, check sensor calibration, and " +
        "review recent measurements and treatment process conditions.";
} else {
    recommendation =
        "Verify the reading and sensor condition, inspect recent " +
        "measurements, and request operator assessment.";
}

const eventType = "water_quality_limit_exceeded";
const lockKey = [
    sensor,
    metric,
    severity,
    eventType
].join("|");

let client;

(async () => {
    try {
        client = await p.connect();
        await client.query("BEGIN");

        // Serialize duplicate checks for this sensor/metric/severity.
        await client.query(
            "SELECT pg_advisory_xact_lock(hashtext($1))",
            [lockKey]
        );

        const existing = await client.query(
            `SELECT event_id, severity
             FROM public.decision_event
             WHERE sensor_id = $1
               AND metric_type = $2
               AND event_type = $3
               AND severity = $4
               AND status IN ('open', 'acknowledged')
             ORDER BY detected_at DESC
             LIMIT 1`,
            [sensor, metric, eventType, severity]
        );

        if (existing.rows.length > 0) {
            await client.query("COMMIT");

            msg.decision = {
                status: "duplicate_suppressed",
                event_id: existing.rows[0].event_id,
                severity,
                sensor_id: sensor,
                metric_type: metric,
                value
            };

            node.send(msg);
            return;
        }

        const eventResult = await client.query(
            `INSERT INTO public.decision_event
                (source, event_type, severity, status,
                 sensor_id, metric_type, observed_value,
                 message, recommended_action, details)
             VALUES
                ('threshold', $1, $2, 'open',
                 $3, $4, $5, $6, $7, $8::jsonb)
             RETURNING event_id, detected_at`,
            [
                eventType,
                severity,
                sensor,
                metric,
                value,
                `${metric} threshold breach: ${value} ${t.unit}.`,
                recommendation,
                JSON.stringify({
                    threshold_limit_id: t.limit_id,
                    unit: t.unit,
                    threshold_description: t.description,
                    simulation: true
                })
            ]
        );

        const event = eventResult.rows[0];

        const actionResult = await client.query(
            `INSERT INTO public.action_log
                (event_id, action_type, status, requested_by, notes)
             VALUES
                ($1, $2, 'proposed', 'system', $3)
             RETURNING action_id`,
            [
                event.event_id,
                "operator_inspection",
                recommendation +
                " Simulation only: no physical equipment was operated."
            ]
        );

        await client.query("COMMIT");

        msg.decision = {
            status: "event_created",
            event_id: event.event_id,
            action_id: actionResult.rows[0].action_id,
            severity,
            sensor_id: sensor,
            metric_type: metric,
            value,
            recommendation
        };

        node.send(msg);
    } catch (err) {
        if (client) {
            try {
                await client.query("ROLLBACK");
            } catch (_) {}
        }

        node.error("WQ decision event failed: " + err.message, msg);
    } finally {
        if (client) client.release();
    }
})();

return;
